code_snippets.parse_list:
def parse(self, response):
    for li in response.css('ul li'):
        detail_url = li.css('a::attr(href)').get()
        if detail_url and detail_url.startswith('https://www.hhs.gov/'):
            yield response.follow(detail_url, callback=self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.css('title::text').get() or response.css('h1::text').get()
    # 假设PDF链接在a标签中，且href以.pdf结尾
    pdf_links = response.css('a[href$=".pdf"]::attr(href)').getall()
    for pdf_link in pdf_links:
        yield {
            'title': title,
            'pdf_url': response.urljoin(pdf_link)
        }
